        let chunks = [Self.text1, Self.text2, Self.text2, Self.done]
        let body = AsyncThrowingStream<Data, Error>(unfolding: {
            try await pulls.sleep(0)
            let index = pulls.delays.count - 1
            return index < chunks.count ? Data(chunks[index].utf8) : nil
        })
        let response = TungoHTTPResponse(statusCode: 200, headers: HTTPHeaders(["Content-Type": "text/event-stream"]), body: body)
        let stream = ChatStream(response: response, decoding: ChatEvent.self, errorIsEvent: true)
        try await Task.sleep(nanoseconds: 200_000_000)
        XCTAssertEqual(pulls.delays.count, 0, "nothing is read before the first iteration")
        var iterator = stream.makeAsyncIterator()
        _ = try await iterator.next()
        try await Task.sleep(nanoseconds: 200_000_000)
        XCTAssertEqual(pulls.delays.count, 1, "a consumer that stopped asking must not be read ahead of")
        _ = try await iterator.next()
        XCTAssertEqual(pulls.delays.count, 2)
    }

